import"./chunk-7CGTOI24.js";var e={slug:"aneis-de-poder-terceira-temporada-estreia",title:"Os An\xE9is de Poder: terceira temporada estreia nesta quarta (11)",dek:"A s\xE9rie da Terra-m\xE9dia volta ao Prime Video depois de dois anos. Relembre onde a hist\xF3ria parou e quem est\xE1 de volta antes do primeiro epis\xF3dio.",section:"series",kind:"noticia",tags:["Senhor dos An\xE9is","Prime Video","Fantasia"],date:"2026-11-09",hero:{ref:"tv:84773",pick:0,alt:"Galadriel em cena de O Senhor dos An\xE9is: Os An\xE9is de Poder"},body:[{p:"*O Senhor dos An\xE9is: Os An\xE9is de Poder* volta nesta quarta-feira, **11 de novembro**, com o primeiro epis\xF3dio da terceira temporada no Prime Video, segundo o TMDB. \xC9 o retorno depois de um intervalo de dois anos: a segunda temporada terminou em outubro de 2024."},{ficha:"tv:84773"},{h2:"Onde paramos"},{p:"A s\xE9rie se passa na Segunda Era da Terra-m\xE9dia, milhares de anos antes de *O Hobbit* e de *O Senhor dos An\xE9is*. Se a primeira temporada apresentou os reinos e as amea\xE7as, a segunda levou a forja dos an\xE9is para o centro da trama e deixou claro o pre\xE7o de confiar em quem promete poder."},{p:"Sem entrar em spoilers, a terceira temporada parte de uma Terra-m\xE9dia bem mais sombria do que aquela que conhecemos em 2022."},{img:"tv:84773",pick:2,caption:"A s\xE9rie \xE9 criada por Patrick McKay e John D. Payne. Imagem de divulga\xE7\xE3o."},{h2:"Quem est\xE1 de volta"},{p:"O elenco principal segue com Morfydd Clark como Galadriel, Robert Aramayo como Elrond, Owain Arthur como o pr\xEDncipe an\xE3o Durin IV e Sophia Nomvete como Disa. Markella Kavenagh, como a p\xE9-peludo Nori, e Ismael Cruz C\xF3rdova, como o elfo Arondir, tamb\xE9m aparecem nos cr\xE9ditos da s\xE9rie."},{quote:"Os An\xE9is de Poder sempre foi melhor quando esqueceu o espet\xE1culo e se concentrou nas amizades. A terceira temporada precisa lembrar disso."},{h2:"Vale come\xE7ar agora?"},{p:"Se voc\xEA nunca assistiu, os 16 epis\xF3dios das duas primeiras temporadas est\xE3o no Prime Video. A s\xE9rie tem altos e baixos, mas a produ\xE7\xE3o \xE9 impressionante e a dupla Elrond e Durin rende alguns dos melhores momentos de fantasia da TV recente."},{box:"A data vem do TMDB e pode variar conforme o fuso de publica\xE7\xE3o da plataforma. A reda\xE7\xE3o ainda n\xE3o viu a nova temporada.",title:"Antes do epis\xF3dio"},{p:"Todas as estreias de s\xE9ries, filmes e games est\xE3o no nosso [calend\xE1rio de lan\xE7amentos](/lancamentos)."}]};var o={source:"TMDB + IGDB",updatedAt:"2026-11-10",calendar:[],games:{},movies:{},tv:{84773:{id:84773,name:"O Senhor dos An\xE9is: Os An\xE9is de Poder",original:"The Lord of the Rings: The Rings of Power",overview:"Tendo in\xEDcio em uma \xE9poca de relativa paz, a s\xE9rie acompanha um grupo de personagens que enfrenta o ressurgimento do mal na Terra-m\xE9dia. Das profundezas escuras das Montanhas de N\xE9voa, das majestosas florestas de Lindon, do bel\xEDssimo reino da ilha de N\xFAmenor, at\xE9 os confins do mapa, esses reinos e personagens criar\xE3o legados que permanecer\xE3o vivos muito al\xE9m de suas partidas.",poster:"/8FPCnfOftiLTHg5wnJxVdtlF8EN.jpg",backdrops:["/achmETPRJZc9QVXsMPgHwYEyNar.jpg","/4pPzwFluOzZg9nOXvECZC4bSSlx.jpg","/9CeFKnC6BFKmXnSLKIWcueJIkoW.jpg","/pdfCr8W0wBCpdjbZXSxnKhZtosP.jpg","/1rO4xoCo4Z5WubK0OwdVll3DPYo.jpg"],genres:["Action & Adventure","Sci-Fi & Fantasy"],cert:"14",creators:["Patrick McKay","John D. Payne"],cast:[{name:"Morfydd Clark",role:"Galadriel"},{name:"Robert Aramayo",role:"Elrond"},{name:"Owain Arthur",role:"Durin IV"},{name:"Sophia Nomvete",role:"Disa"},{name:"Markella Kavenagh",role:"Elanor 'Nori' Brandyfoot"},{name:"Ismael Cruz Cordova",role:"Arondir"}],networks:["Prime Video"],first:"2022-09-01",last:"2024-10-03",status:"Em produ\xE7\xE3o",seasons:3,episodes:24,next:{date:"2026-11-11",season:3,episode:1},country:"US"}}};export{o as media,e as post};
